import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/tmp/app.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY, username TEXT UNIQUE,
        password_hash TEXT, email TEXT, is_admin INTEGER DEFAULT 0)''')
    db.execute('''CREATE TABLE IF NOT EXISTS documents (
        id INTEGER PRIMARY KEY, owner_id INTEGER, title TEXT,
        content TEXT, classification TEXT DEFAULT 'internal')''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY, action TEXT, user_id INTEGER,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP, details TEXT)''')
    db.commit()
    db.close()

@app.route('/api/documents/search', methods=['GET'])
def search_documents():
    """Search documents by title - supports advanced query syntax"""
    query = request.args.get('q', '')
    user_id = request.headers.get('X-User-Id', '0')
    classification = request.args.get('classification', 'internal')

    # Log the search for compliance
    db = get_db()
    db.execute("INSERT INTO audit_log (action, user_id, details) VALUES (?, ?, ?)",
               ('search', int(user_id), f'query={query}'))
    db.commit()

    # Build search query with classification filter
    sql = f"SELECT id, title, content, classification FROM documents WHERE classification = '{classification}' AND title LIKE '%{query}%'"

    try:
        results = db.execute(sql).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 400

@app.route('/api/documents', methods=['POST'])
def create_document():
    """Create a new document"""
    data = request.get_json()
    user_id = request.headers.get('X-User-Id', '0')
    db = get_db()
    db.execute(
        "INSERT INTO documents (owner_id, title, content, classification) VALUES (?, ?, ?, ?)",
        (int(user_id), data.get('title', ''), data.get('content', ''), data.get('classification', 'internal'))
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
def get_document(doc_id):
    """Retrieve a specific document by ID"""
    user_id = request.headers.get('X-User-Id', '0')
    db = get_db()
    # Note: no ownership check - relies on upstream authorization
    result = db.execute("SELECT * FROM documents WHERE id = ?", (doc_id,)).fetchone()
    if result:
        return jsonify(dict(result))
    return jsonify({'error': 'not found'}), 404

@app.route('/api/users/<int:uid>/profile', methods=['GET'])
def get_profile(uid):
    """Get user profile - password_hash excluded via column selection"""
    db = get_db()
    result = db.execute("SELECT id, username, email, is_admin FROM users WHERE id = ?", (uid,)).fetchone()
    if result:
        return jsonify(dict(result))
    return jsonify({'error': 'not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.3.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
